  "For high-traffic publishers, agencies and white-label integrations.": { de: "Für reichweitenstarke Publisher, Agenturen und White-Label-Integrationen.", es: "Para medios con mucho tráfico, agencias e integraciones de marca blanca.", pt: "Para publishers com muito tráfego, agências e integrações white-label.", fr: "Pour les éditeurs à fort trafic, les agences et les intégrations en marque blanche.", it: "Per editori ad alto traffico, agenzie e integrazioni white-label." },
  "Recommended": { de: "Empfohlen", es: "Recomendado", pt: "Recomendado", fr: "Recommandé", it: "Consigliato" },
  "Personal reply within one business day": { de: "Persönliche Antwort innerhalb eines Werktags", es: "Respuesta personal en un día laborable", pt: "Resposta pessoal num dia útil", fr: "Réponse personnalisée sous un jour ouvré", it: "Risposta personale entro un giorno lavorativo" },
  "Billing details and payment are completed on the next page.": { de: "Rechnungsdaten und Zahlung werden auf der nächsten Seite abgeschlossen.", es: "Los datos de facturación y el pago se completan en la página siguiente.", pt: "Os dados de faturação e o pagamento são concluídos na página seguinte.", fr: "Les informations de facturation et le paiement sont finalisés à l’étape suivante.", it: "I dati di fatturazione e il pagamento vengono completati nella pagina successiva." },
  "Config options": { de: "Konfigurationsoptionen", es: "Opciones de configuración", pt: "Opções de configuração", fr: "Options de configuration", it: "Opzioni di configurazione" },
  "Required paid publisher key": { de: "Erforderlicher kostenpflichtiger Publisher-Schlüssel", es: "Clave de publisher de pago obligatoria", pt: "Chave paga de publisher obrigatória", fr: "Clé éditeur payante requise", it: "Chiave publisher a pagamento obbligatoria" },
  "Optional competition filter": { de: "Optionaler Wettbewerbsfilter", es: "Filtro de competición opcional", pt: "Filtro de competição opcional", fr: "Filtre de compétition facultatif", it: "Filtro competizione facoltativo" },
  "Optional exact match id": { de: "Optionale exakte Spiel-ID", es: "ID exacto de partido opcional", pt: "ID exato do jogo opcional", fr: "Identifiant exact du match facultatif", it: "ID esatto della partita facoltativo" },
  "Multiple selected match ids, comma-separated": { de: "Mehrere ausgewählte Spiel-IDs, durch Kommas getrennt", es: "Varios ID de partidos, separados por comas", pt: "Vários IDs de jogos, separados por vírgulas", fr: "Plusieurs identifiants de matchs, séparés par des virgules", it: "Più ID partita, separati da virgole" },
  "English or German widget interface": { de: "Deutsche oder englische Widget-Oberfläche", es: "Interfaz del widget en inglés o alemán", pt: "Interface do widget em inglês ou alemão", fr: "Interface du widget en anglais ou en allemand", it: "Interfaccia del widget in inglese o tedesco" },
  "Fixed model or visitor model switcher": { de: "Festes Modell oder Modellauswahl für Besucher", es: "Modelo fijo o selector de modelo para visitantes", pt: "Modelo fixo ou seletor de modelo para visitantes", fr: "Modèle fixe ou choix du modèle par le visiteur", it: "Modello fisso o selettore del modello per i visitatori" },
  "Hex color, e.g. #7df5c1": { de: "Hex-Farbe, z. B. #7df5c1", es: "Color hexadecimal, p. ej. #7df5c1", pt: "Cor hexadecimal, por ex. #7df5c1", fr: "Couleur hexadécimale, p. ex. #7df5c1", it: "Colore esadecimale, ad es. #7df5c1" },
  "Hex color": { de: "Hex-Farbe", es: "Color hexadecimal", pt: "Cor hexadecimal", fr: "Couleur hexadécimale", it: "Colore esadecimale" },
  "Widget builder": { de: "Widget-Builder", es: "Creador de widgets", pt: "Criador de widgets", fr: "Créateur de widgets", it: "Configuratore di widget" },
  "Choose preview games without a key, adjust the widget and copy the finished embed code when you are ready to publish.": { de: "Wähle Vorschau-Spiele ohne Schlüssel, passe das Widget an und kopiere den fertigen Einbettungscode, sobald du veröffentlichen möchtest.", es: "Elige partidos de ejemplo sin clave, ajusta el widget y copia el código de inserción cuando esté listo para publicarse.", pt: "Escolha jogos de pré-visualização sem chave, ajuste o widget e copie o código de incorporação quando estiver pronto para publicar.", fr: "Choisissez des matchs d’aperçu sans clé, ajustez le widget puis copiez le code d’intégration lorsque vous êtes prêt à publier.", it: "Scegli le partite di anteprima senza chiave, configura il widget e copia il codice di incorporamento quando sei pronto a pubblicare." },
  "Publisher API key (optional for preview)": { de: "Publisher-API-Schlüssel (für Vorschau optional)", es: "Clave API del publisher (opcional para la vista previa)", pt: "Chave API do publisher (opcional para a pré-visualização)", fr: "Clé API éditeur (facultative pour l’aperçu)", it: "Chiave API publisher (facoltativa per l’anteprima)" },
  "Publisher domain": { de: "Publisher-Domain", es: "Dominio del publisher", pt: "Domínio do publisher", fr: "Domaine de l’éditeur", it: "Dominio del publisher" },
  "Sport": { de: "Sportart", es: "Deporte", pt: "Desporto", fr: "Sport", it: "Sport" },
