  "Widget language": { de: "Widget-Sprache", es: "Idioma del widget", pt: "Idioma do widget", fr: "Langue du widget", it: "Lingua del widget" },
  "Search team, player, competition or match id": { de: "Team, Spieler, Wettbewerb oder Spiel-ID suchen", es: "Buscar equipo, jugador, competición o ID del partido", pt: "Pesquisar equipa, jogador, competição ou ID do jogo", fr: "Rechercher une équipe, un joueur, une compétition ou un identifiant de match", it: "Cerca squadra, giocatore, competizione o ID partita" },
  "Search matches": { de: "Spiele suchen", es: "Buscar partidos", pt: "Pesquisar jogos", fr: "Rechercher des matchs", it: "Cerca partite" },
  "Search for a team, player or competition, then select a game for the preview.": { de: "Suche nach einem Team, Spieler oder Wettbewerb und wähle danach ein Spiel für die Vorschau.", es: "Busca un equipo, jugador o competición y selecciona después un partido para la vista previa.", pt: "Pesquise uma equipa, jogador ou competição e selecione depois um jogo para a pré-visualização.", fr: "Recherchez une équipe, un joueur ou une compétition, puis sélectionnez un match pour l’aperçu.", it: "Cerca una squadra, un giocatore o una competizione, quindi seleziona una partita per l’anteprima." },
  "Accent": { de: "Akzent", es: "Acento", pt: "Destaque", fr: "Accent", it: "Accento" },
  "Background": { de: "Hintergrund", es: "Fondo", pt: "Fundo", fr: "Arrière-plan", it: "Sfondo" },
