  "Information pursuant to § 5 DDG": { de: "Angaben gemäß § 5 DDG", es: "Información conforme al § 5 DDG", pt: "Informações nos termos do § 5 DDG", fr: "Informations conformément au § 5 DDG", it: "Informazioni ai sensi del § 5 DDG" },
