export function translateText(value: string, locale: SiteLocale): string {
  if (locale === "en") return value;
  const normalized = value.trim().replace(/\s+/g, " ");
  const translated = TRANSLATIONS[normalized]?.[locale]
    ?? CASE_INSENSITIVE_TRANSLATIONS.get(normalized.toLocaleLowerCase("en-US"))?.[locale];
  if (translated) return translated;

  const numberedLabel = normalized.match(/^(\d+\.\s*)(.+)$/);
  if (numberedLabel) {
    const label = translateText(numberedLabel[2], locale);
    if (label !== numberedLabel[2]) return `${numberedLabel[1]}${label}`;
  }

  return value;
}

const CASE_INSENSITIVE_TRANSLATIONS = new Map(
  Object.entries(TRANSLATIONS).map(([key, translation]) => [key.toLocaleLowerCase("en-US"), translation])
);
